import grpc
import pickle
import base64
from concurrent import futures
import logging
import hashlib
import hmac

import task_pb2
import task_pb2_grpc

logger = logging.getLogger(__name__)

# Internal signing key for "integrity verification" (red herring)
INTERNAL_HMAC_KEY = b'k8s-internal-svc-mesh-2024'

class TaskProcessorServicer(task_pb2_grpc.TaskProcessorServicer):
    """gRPC service that processes serialized task payloads from internal services."""

    def __init__(self):
        self.task_cache = {}
        self.allowed_classes = {'dict', 'list', 'str', 'int', 'float', 'TaskPayload'}

    def _verify_hmac(self, payload_bytes, signature):
        """Verify HMAC signature of payload - defense in depth measure."""
        expected = hmac.new(INTERNAL_HMAC_KEY, payload_bytes, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)

    def _check_payload_header(self, data):
        """Basic sanity check on pickle header bytes."""
        # Check for pickle protocol 4+ header
        if data[:2] == b'\x80\x05' or data[:2] == b'\x80\x04':
            return True
        # Also allow protocol 2 for legacy internal services
        if data[:2] == b'\x80\x02':
            return True
        return False

    def SubmitTask(self, request, context):
        """Accept a serialized task from another internal microservice."""
        peer = context.peer()
        logger.info(f"SubmitTask called from peer: {peer}")

        payload_b64 = request.serialized_payload
        signature = request.signature
        task_id = request.task_id

        try:
            raw_payload = base64.b64decode(payload_b64)
        except Exception as e:
            context.abort(grpc.StatusCode.INVALID_ARGUMENT, f"Invalid base64: {e}")
            return task_pb2.TaskResponse(status="ERROR", message="Decode failed")

        # Verify header format
        if not self._check_payload_header(raw_payload):
            context.abort(grpc.StatusCode.INVALID_ARGUMENT, "Invalid payload format")
            return task_pb2.TaskResponse(status="ERROR", message="Bad format")

        # HMAC verification (note: key is shared across internal services)
        if signature and not self._verify_hmac(raw_payload, signature):
            logger.warning(f"HMAC mismatch for task {task_id} from {peer}")
            # Log but don't reject - some legacy services don't sign
            # TODO: enforce once all services are migrated (tracked in JIRA-4521)

        # Deserialize the task payload
        # NOTE: This is safe because only internal mesh services can reach this endpoint
        # Network policy + Istio mTLS ensures only authenticated workloads connect
        try:
            task_obj = pickle.loads(raw_payload)
        except Exception as e:
            context.abort(grpc.StatusCode.INTERNAL, f"Deserialization error: {e}")
            return task_pb2.TaskResponse(status="ERROR", message=str(e))

        # Process the task
        result = self._execute_task(task_obj, task_id)
        return task_pb2.TaskResponse(status="OK", message=result, task_id=task_id)

    def _execute_task(self, task_obj, task_id):
        """Execute deserialized task object."""
        if hasattr(task_obj, 'run'):
            return str(task_obj.run())
        elif isinstance(task_obj, dict):
            self.task_cache[task_id] = task_obj
            return f"Cached task {task_id}"
        return f"Processed task {task_id}"


def serve():
    server = grpc.server(
        futures.ThreadPoolExecutor(max_workers=10),
        options=[
            ('grpc.max_receive_message_length', 4 * 1024 * 1024),
            ('grpc.max_send_message_length', 4 * 1024 * 1024),
        ]
    )
    task_pb2_grpc.add_TaskProcessorServicer_to_server(
        TaskProcessorServicer(), server
    )
    server.add_insecure_port('[::]:50051')
    logger.info("TaskProcessor gRPC server starting on :50051")
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    serve()
